          "content": "图书馆那次改稿，你们没有立刻决定用哪一个结尾。\n\n林知夏说，她以后想继续采访，想去现在还没去过的地方。你问她是不是每次回来，都有这么多事情想讲。\n\n她说也不一定。有的采访很普通，坐车回来的时候反而更想找人说说话。\n\n你记住了这句话。\n\n第30周，走到校门口，她停下整理记录本。你站在旁边，没有像平常那样说一句明天见就走。\n\n“还有事？”\n\n你说，有。\n\n这次你没有把话放在一道题后面，也没有等她先猜。你告诉她，自己现在会很想收到她的消息，白天遇见事情，也常常先想到晚上可以讲给她听。\n\n说到最后，你才把喜欢两个字说出来。\n\n她听完，手还按在记录本上。\n\n“我愿意继续了解。”她说，“但有些事情，我现在还不能答应。”\n\n你问她是不是仍可以像现在这样联系。\n\n她点头，说可以，也希望各自原来的安排继续留着。\n\n回家的路上，你给她发了一张校门口正在收纸箱的照片。她回复得很快，问你是不是又准备写一篇关于鸡腿的文章。\n\n你在车站笑了很久。",
