      "content": "蓝色活页本空出了一张横向的纸。你可以把下一段学习生活写得具体些：想学什么，课程怎样安排，住在哪里，去一趟要多久，日常开销由什么承担。本次成绩已经确定，两项虚构项目的申请条件列在下方。成绩不能代替你回答生活上的这些问题。\n\n现在可以先了解，再决定是否申请。拿不准的一栏留白，不必为了交出一张漂亮的表，把不想去的地方写成“愿意”。",
