      "title": "休整筹备",
      "content": "如果你想先空出一段时间，可以把它安排成一件具体的事：在哪里生活，日常开销怎样承担，消息多久查看一次，何时再谈升学、复读或工作。想休整，不必等到身体或情绪被一个数字判为“不合格”。\n\n这也不是一张永久退出的声明。你可以暂时放慢，把需要继续处理的事情放在能找到的位置。",
