      "title": "榆桥的街口",
      "content": "你收到了榆桥大学的答复，最终选定这所藏在城市旧街区里的学校。教学楼没有宣传册里常见的大片草坪，窗外是一家早点店的雨棚。报到那天，有人拖着箱子拐错楼门，你也刚找完教室，便一起对着墙上的指示看了好一会儿。\n\n第一门通识课要求小组记录街口怎样使用公共空间。你负责整理观察结果，才发现数据表能放下人数和时段，却放不下店主说话时那个停顿。组员把那句话重新补回去，你们为图例与文字改了几次，最后交出去的报告比任何一个人原先设想的都具体。\n\n有些你想上的课程没有排进这一学期，有些方向还要等之后申请，选择的范围始终有边界。你在蓝色活页本里给它们留下一页，先去上已经选好的课。某天早上，早点店老板看见你，问“还是上回那种？”你点头，拿着热纸袋上楼。新生活开始有了能认出你的地方，作业里的街口，也变成每天经过的街口。"
