      "title": "城南的末班车",
      "content": "城南学院确认接收你后，你去看了一次校园。教学楼在公交线路尽头，选课表比你最早看过的那份短。有两门感兴趣的课暂时不开，你问过之后，把名字写在本子里，没有因为一声“以后再看”就当它们已经出现。\n\n入学后的基础课上，你卡在一个需要补回旧知识的地方。课间去问，任课老师把问题拆开，让你先做其中一步。你没有立刻补完所有缺口，第二天仍带着同一页纸过去。窗边的座位慢慢固定下来，旁边的人认得那张折过角的草稿，也会把自己没弄明白的地方拿过来。\n\n一次留在教室太晚，你差点错过末班车。司机看见你跑来，停了一会儿。车开过一排已经关门的店，你坐下，才发现笔还攥在手里。新的学习资源需要主动找，时间和距离也都有具体的限制。你把车次写进蓝色活页本，旁边是明天要接着问的问题。以后想往哪里走还没有全部定好，眼前这一步已经有了一间可以再去的教室。"
