      "title": "旧稿仍然能打开",
      "content": "你保留了竞赛旧稿，往后仍愿意把它当作爱好。一个空闲下午，你打开以前的程序，先被一行过长的变量名逗笑，再试着看懂自己当时为什么这样写。没有人要求你在限定时间里交出答案，也不用先参加一场比赛，这半小时才算数。有一题仍想不明白，你把问题夹回本子，关掉电脑去做别的事。OI没有重新占满生活，也没有因为AFO三个字就失去所有用处。它如今可以是一件想起来便打开、暂时没有空便放下的事。"
