      "title": "只留一页在手边",
      "content": "你把大部分竞赛稿归好，只留下一页在蓝色活页本里。那页纸不负责证明当年的成绩，也不替未来的选择站队；它只是你仍想带着的一小段经历。以后收拾新书、旧材料或工作资料时，它会偶尔翻出来。某个角上的涂改已经记不起原因，你也没有为了补全记忆把所有箱子重新打开。过去因此有了一个有限的位置，日常还能装下别的内容。有人问起竞赛，你可以讲一点，也可以只说曾经做过，然后继续眼前的话题。"
