      "content": "原教练老师接过那箱旧稿，问你要不要在外面写名字。你写好，把其中一张单独取出看了看，又放回去。暂时交他保管不是毁掉，也不是约定一定回到训练里。以后想取，可以再联系；现在不想看，桌面就先留给别的事情。原教练老师没有拿出一道题考你还记得多少，只提醒箱子放在哪里。离开时，你手里轻了一些，路上的声音反而清楚起来。那段经历没有被判为浪费，也没有被要求随身携带，才能承认它确实发生过。"
